@dataclass
class OriginResult:
    chain: List[ProvenanceInfo] = field(default_factory=lambda: [])  # from the ROM towards the queried bytes; a 'computed' step names code that produced bytes rather than copying them
    taint: List[TaintInfo] = field(default_factory=lambda: [])  # runs of equal labels
    file_reads: List[ProvenanceInfo] = field(default_factory=lambda: [])  # card reads of the ROM files named by the labels, with the code that loaded them (newest first)
    origin_enabled: bool = False
    state_loaded_frame: int = 0  # a savestate was loaded at this frame: labels were rebuilt from content then, so memory not recognised has no origin; 0 = none
    archive: List[ArchiveSegment] = field(default_factory=lambda: [])  # runs of the queried bytes equal to files of a detected ROM archive, by content (works without recording); at most 256, in address order
    archive_truncated: bool = False  # more runs follow: query again from the end of the last one
    archive_status: str = ""  # none (no archive detected), indexing, ready or failed: <reason>
    containers: List[ArchiveSegment] = field(default_factory=lambda: [])  # runs of the queried bytes equal to files inside NARC or SDAT containers, by content (works without recording); at most 256, in address order. Their paths are '/file.narc:member'
    containers_truncated: bool = False  # more runs follow: query again from the end of the last one
    containers_status: str = ""  # none (no NARC or SDAT files), indexing or ready

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "OriginResult":
        kw = {}
        if "chain" in d and d["chain"] is not None: kw["chain"] = [ProvenanceInfo.from_dict(x) for x in d["chain"]]
        if "taint" in d and d["taint"] is not None: kw["taint"] = [TaintInfo.from_dict(x) for x in d["taint"]]
        if "file_reads" in d and d["file_reads"] is not None: kw["file_reads"] = [ProvenanceInfo.from_dict(x) for x in d["file_reads"]]
        if "origin_enabled" in d: kw["origin_enabled"] = d["origin_enabled"]
        if "state_loaded_frame" in d: kw["state_loaded_frame"] = d["state_loaded_frame"]
        if "archive" in d and d["archive"] is not None: kw["archive"] = [ArchiveSegment.from_dict(x) for x in d["archive"]]
        if "archive_truncated" in d: kw["archive_truncated"] = d["archive_truncated"]
        if "archive_status" in d: kw["archive_status"] = d["archive_status"]
        if "containers" in d and d["containers"] is not None: kw["containers"] = [ArchiveSegment.from_dict(x) for x in d["containers"]]
        if "containers_truncated" in d: kw["containers_truncated"] = d["containers_truncated"]
        if "containers_status" in d: kw["containers_status"] = d["containers_status"]
        return cls(**kw)

    def to_dict(self) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        out["chain"] = [x.to_dict() for x in self.chain]
        out["taint"] = [x.to_dict() for x in self.taint]
        out["file_reads"] = [x.to_dict() for x in self.file_reads]
        out["origin_enabled"] = self.origin_enabled
        out["state_loaded_frame"] = self.state_loaded_frame
        out["archive"] = [x.to_dict() for x in self.archive]
        out["archive_truncated"] = self.archive_truncated
        out["archive_status"] = self.archive_status
        out["containers"] = [x.to_dict() for x in self.containers]
        out["containers_truncated"] = self.containers_truncated
        out["containers_status"] = self.containers_status
        return out


