@dataclass
class KbListResult:
    kind: str = ""
    total: int = 0  # matches before paging
    truncated: bool = False  # more matches follow: query again with offset = next_offset
    next_offset: int = 0
    functions: Optional[List[KbFunctionInfo]] = None  # sorted by address; only the list of the requested kind is present
    labels: Optional[List[KbLabelInfo]] = None  # sorted by address
    data_objects: Optional[List[KbDataObjectInfo]] = None  # sorted by address
    types: Optional[List[KbTypeInfo]] = None  # sorted by name
    annotations: Optional[List[KbAnnotationInfo]] = None  # oldest first
    bookmarks: Optional[List[KbBookmarkInfo]] = None  # oldest first
    decode_overrides: Optional[List[KbDecodeOverrideInfo]] = None  # sorted by CPU and start
    modules: Optional[List[KbModuleInfo]] = None

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "KbListResult":
        kw = {}
        if "kind" in d: kw["kind"] = d["kind"]
        if "total" in d: kw["total"] = d["total"]
        if "truncated" in d: kw["truncated"] = d["truncated"]
        if "next_offset" in d: kw["next_offset"] = d["next_offset"]
        if "functions" in d and d["functions"] is not None: kw["functions"] = [KbFunctionInfo.from_dict(x) for x in d["functions"]]
        if "labels" in d and d["labels"] is not None: kw["labels"] = [KbLabelInfo.from_dict(x) for x in d["labels"]]
        if "data_objects" in d and d["data_objects"] is not None: kw["data_objects"] = [KbDataObjectInfo.from_dict(x) for x in d["data_objects"]]
        if "types" in d and d["types"] is not None: kw["types"] = [KbTypeInfo.from_dict(x) for x in d["types"]]
        if "annotations" in d and d["annotations"] is not None: kw["annotations"] = [KbAnnotationInfo.from_dict(x) for x in d["annotations"]]
        if "bookmarks" in d and d["bookmarks"] is not None: kw["bookmarks"] = [KbBookmarkInfo.from_dict(x) for x in d["bookmarks"]]
        if "decode_overrides" in d and d["decode_overrides"] is not None: kw["decode_overrides"] = [KbDecodeOverrideInfo.from_dict(x) for x in d["decode_overrides"]]
        if "modules" in d and d["modules"] is not None: kw["modules"] = [KbModuleInfo.from_dict(x) for x in d["modules"]]
        return cls(**kw)

    def to_dict(self) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        out["kind"] = self.kind
        out["total"] = self.total
        out["truncated"] = self.truncated
        out["next_offset"] = self.next_offset
        if self.functions is not None: out["functions"] = [x.to_dict() for x in self.functions]
        if self.labels is not None: out["labels"] = [x.to_dict() for x in self.labels]
        if self.data_objects is not None: out["data_objects"] = [x.to_dict() for x in self.data_objects]
        if self.types is not None: out["types"] = [x.to_dict() for x in self.types]
        if self.annotations is not None: out["annotations"] = [x.to_dict() for x in self.annotations]
        if self.bookmarks is not None: out["bookmarks"] = [x.to_dict() for x in self.bookmarks]
        if self.decode_overrides is not None: out["decode_overrides"] = [x.to_dict() for x in self.decode_overrides]
        if self.modules is not None: out["modules"] = [x.to_dict() for x in self.modules]
        return out


