@dataclass
class RecordingParams:
    enabled: Optional[bool] = None  # recording switch
    write_history: Optional[bool] = None
    data_origin: Optional[bool] = None
    history_cap: Optional[int] = None  # entries
    history_include: Optional[List[AddrRange]] = None  # write history keeps only writes to these ranges (empty: everywhere)
    history_exclude_writers: Optional[List[AddrRange]] = None  # write history skips writes by code in these ranges
    history_bulk_threshold: Optional[int] = None  # write history skips the bytes of a sequential run (copy, fill, unpacking) beyond this many; 0 keeps everything (default 1024)
    history_skip_stack: Optional[bool] = None  # write history skips CPU writes near the writer's stack pointer: spills and locals (default on)
    history_skip_unchanged: Optional[bool] = None  # write history skips writes that store the value already there (default on)
    history_file_mb: Optional[int] = None  # keep write history in a file of this many MB in the project folder (about 32,000 writes per MB; 0 = in memory). Starts history afresh
    save_session: Optional[bool] = None  # save a session file now and keep recording (File > Save recording session now)
    history_keep_mb: Optional[int] = None  # disk budget for saved sessions' history files (.dswbh); the oldest are deleted first, never the newest (default 2048)
    origin_all_rom_files: Optional[bool] = None  # make every ROM file a source (the default)
    origin_follow_addresses: Optional[bool] = None  # follow table lookups: a loaded value also takes the labels of its address registers (off by default)
    sources_add: List[OriginSourceSpec] = field(default_factory=lambda: [])
    sources_remove: List[int] = field(default_factory=lambda: [])  # source ids

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> "RecordingParams":
        kw = {}
        if "enabled" in d: kw["enabled"] = d["enabled"]
        if "write_history" in d: kw["write_history"] = d["write_history"]
        if "data_origin" in d: kw["data_origin"] = d["data_origin"]
        if "history_cap" in d: kw["history_cap"] = d["history_cap"]
        if "history_include" in d and d["history_include"] is not None: kw["history_include"] = [AddrRange.from_dict(x) for x in d["history_include"]]
        if "history_exclude_writers" in d and d["history_exclude_writers"] is not None: kw["history_exclude_writers"] = [AddrRange.from_dict(x) for x in d["history_exclude_writers"]]
        if "history_bulk_threshold" in d: kw["history_bulk_threshold"] = d["history_bulk_threshold"]
        if "history_skip_stack" in d: kw["history_skip_stack"] = d["history_skip_stack"]
        if "history_skip_unchanged" in d: kw["history_skip_unchanged"] = d["history_skip_unchanged"]
        if "history_file_mb" in d: kw["history_file_mb"] = d["history_file_mb"]
        if "save_session" in d: kw["save_session"] = d["save_session"]
        if "history_keep_mb" in d: kw["history_keep_mb"] = d["history_keep_mb"]
        if "origin_all_rom_files" in d: kw["origin_all_rom_files"] = d["origin_all_rom_files"]
        if "origin_follow_addresses" in d: kw["origin_follow_addresses"] = d["origin_follow_addresses"]
        if "sources_add" in d and d["sources_add"] is not None: kw["sources_add"] = [OriginSourceSpec.from_dict(x) for x in d["sources_add"]]
        if "sources_remove" in d: kw["sources_remove"] = d["sources_remove"]
        return cls(**kw)

    def to_dict(self) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        if self.enabled is not None: out["enabled"] = self.enabled
        if self.write_history is not None: out["write_history"] = self.write_history
        if self.data_origin is not None: out["data_origin"] = self.data_origin
        if self.history_cap is not None: out["history_cap"] = self.history_cap
        if self.history_include is not None: out["history_include"] = [x.to_dict() for x in self.history_include]
        if self.history_exclude_writers is not None: out["history_exclude_writers"] = [x.to_dict() for x in self.history_exclude_writers]
        if self.history_bulk_threshold is not None: out["history_bulk_threshold"] = self.history_bulk_threshold
        if self.history_skip_stack is not None: out["history_skip_stack"] = self.history_skip_stack
        if self.history_skip_unchanged is not None: out["history_skip_unchanged"] = self.history_skip_unchanged
        if self.history_file_mb is not None: out["history_file_mb"] = self.history_file_mb
        if self.save_session is not None: out["save_session"] = self.save_session
        if self.history_keep_mb is not None: out["history_keep_mb"] = self.history_keep_mb
        if self.origin_all_rom_files is not None: out["origin_all_rom_files"] = self.origin_all_rom_files
        if self.origin_follow_addresses is not None: out["origin_follow_addresses"] = self.origin_follow_addresses
        out["sources_add"] = [x.to_dict() for x in self.sources_add]
        out["sources_remove"] = self.sources_remove
        return out


